INSERT INTO match_hypotheses VALUES(39,56,34,NULL,'D2','알리송 중점(평가·발언·브라질 매체)','에메리 1차 발언 확보(보호·신뢰 어조). MOMS 「수비 임무 소홀」은 16′ 전환 한 장면으로 한정 채택. 브라질 매체 0 확정(2회차).','E&S · Tanswell · Bains · WS','pending','남은 것은 바이킹전 기용',34,1077,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(40,55,1,'H1','D0','만잠비↔음바예 자리 교대가 많다','두 선수가 함께 x≥40에서 공을 만진 지공 체인은 6개다. 「음바예 바깥·만잠비 안」 구성이 6체인, **「만잠비 바깥·음바예 안」 교대가 2체인(26.8′·69.7′)**이다. 만잠비 평균 y 62.4로 CAM인데 왼쪽으로 치우쳤다(pos_class LAM). x≥40 터치는 좌 하프스페이스 13·중앙 7·좌측 터치라인 5다','WS · SS · Tanswell','partial','교대는 있었지만 기본 배치는 「음바예 바깥·만잠비 좌 하프스페이스」다. 만잠비가 왼쪽으로 빠지는 경향은 강하게 확인됐다. Tanswell 19:08Z는 「Because Mbaye is playing as a left winger, unusual in an Emery system, Manzambi is playing close to him」(음바예가 에메리 시스템에서는 드물게 정통 왼쪽 윙어로 뛰어서 만잠비가 그에게 붙어 있다)이라고 썼다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(41,55,2,'H1','D0','음바예의 좌↔우 횡단은 주로 세트피스 이후다','음바예의 우측 레인(열3~4) 터치는 세트피스 직후 20초 안에 2건, 그 밖에는 **0건**이다','WS','match','표본 2',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(42,55,3,'H1·메모2','D0','만잠비가 좌측으로 빠지고 음바예가 중앙에서 받아 전진한다(반복)','음바예가 받은 전진 패스(≥15) 9개 중 8개가 **좌측 레인 직선 수신**이다. 대각 안쪽은 71′ 만잠비→음바예 1개뿐이다. 만잠비→음바예 전진 패스는 3개(23′·27′·71′)다','WS','partial','「만잠비 좌측 이탈 → 음바예 안쪽 수신」 장면은 2체인에서 확인된다. 반복 빈도는 「음바예 바깥 수신」이 압도한다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(43,55,4,'H2','D0','캐시↔맥긴 교대가 있고, 「맥긴 안쪽·캐시 터치라인」이 더 잦다','같은 체인 안 교대 장면은 A(맥긴 안·캐시 밖) **1** · B(맥긴 밖·캐시 안) **2**이고 모두 전반이다. 캐시의 x≥50 터치는 전반 터치라인 13·하프스페이스 7이다. 맥긴의 지공 레인은 우측 터치라인 10·중앙 4·우 하프스페이스 2다. 상대 해설(auto-caption)은 「Mekin orta sahalaşıyor işte bek yüksek çıkıyor」(맥긴이 중앙 미드필더처럼 들어가면 풀백이 높이 올라간다)라고 말했다','WS · 터키 하프타임 방송','partial','교대 자체는 실측(3체인)과 상대 해설로 확인된다. 「A가 더 잦다」는 이 경기 이벤트로는 불일치(A1 < B2)지만 표본이 3이라 판정력이 약하다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(44,55,5,NULL,'D0','캐시가 측면을 벌리며 올라온다','전반 터치의 69%가 x≥50이고, 교체 전 터치라인 비중은 72%다. 크로스 3개는 모두 우측 터치라인에서 나왔고 모두 실패했다. UEFA 스프린트 13','WS · UEFA','match',NULL,NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(45,55,6,NULL,'D0','(시즌 축) 캐시의 슛은 하프스페이스에서 많이 나온다','이 경기 슛은 2개뿐이고 둘 다 세트피스(코너·FK) 상황이다. 오픈플레이 슛은 0개다','SS 슛맵','undecided','이 경기 표본 0 · 커리어 판정은 obs#1010 유지',NULL,1010,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(46,55,7,NULL,'D0','캐시의 FC 역할은 「윙백·Support」 또는 「공격형 윙백·Support」다','점유 국면 그리드는 **공격형 윙백·Support .867** > 윙백·Balanced .803 > 윙백·Support .786 순이다. 전체 그리드는 윙백·Balanced .870 > 공격형 윙백·Support .844 > 윙백·Support .837 순이다','K · WS · SS','partial','점유 국면 1위는 공격형 윙백·Support다. 「윙백·Support」는 두 그리드 모두 3위다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(47,55,8,NULL,'D0','인게임 RB를 「윙백·Balanced」로 쓰는 이유(맥긴 안쪽·캐시 터치라인 고정)','전체 그리드 1위가 윙백·Balanced .870이다. 다만 2위와 Δ.027이라 **실측 무결정**이다. 캐시 터치라인 비중 72%는 「터치라인 고정」과 맞는다','K · WS','partial','무결정 구간 — 영상·사용자 판단이 tie-break 권한을 갖는다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(48,55,9,'H3','D0','잭슨은 어드밴스드 포워드 지원처럼 좌우·2선까지 넓고 깊게 움직인다','터치가 5개 레인 전부에 있다(우 하프스페이스 6·좌 하프스페이스 5·중앙 5·우측 4·좌측 2). 좌우 폭 53.7m. 하프라인 아래 터치 9%. **후반 평균 x 63.9m(전반 85.5m)**. 커널은 **어드밴스드 포워드·Support .749(Δ.228 · 2위 포처·Support .521)**. UEFA 스프린트 30(팀 최다)·최고 34.08km/h','K · WS · UEFA','match','폭은 경기 내내, 깊이는 후반',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(49,55,10,'H4','D0','카마라가 바클리보다 높다','이벤트 평균 x: 전반 카마라 55.0m vs 바클리 55.3m(같음), 후반 47.3 vs 56.2. UEFA 트래킹 평균(경기 전체 · 공 없는 시간 포함)은 48.7m vs 48.5m로 같다','WS · UEFA','mismatch','전반에도 높이가 같았고, 경기 전체로는 바클리가 더 높다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(50,55,11,'H4','D0','의도된 우측 빌드업으로 좌측 뒷공간(음바예)을 노렸다','빌드업 체인 18개의 전개 측면은 좌 5·중 4·우 6(전반 3·1·3)이다. 첫 패스 방향은 우 5·좌 4·중 9다. 스즈키 짧은 패스 수신은 **좌 CB 파우 토레스 7** vs 린델뢰프 3이다. 우측→좌측 뒷공간 전환 패스는 7′ 카마라→음바예 1개다','WS','mismatch','불일치(측면 쏠림) — 우측 편중이 없고 GK 첫 패스는 오히려 왼쪽이었다. 「의도」는 회견 확인 전 가설이다 → D+2 재판정',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(51,55,12,'H5','D0','스즈키가 짧은 패스를 어디서 주고받나','짧은 패스(<32m) 15개는 **모두 성공**했다. 출발 위치는 박스 안 12·박스 밖 3이고, 골라인에서 평균 11.3m·최대 20.5m다. 출발 레인은 중앙 13·우 하프스페이스 2다. 수신자는 토레스 7·린델뢰프 3·카마라 1·만잠비 1이다. 받은 패스는 14개(토레스 7·린델뢰프 3·캐시 2·바클리 1·고메스 1)이고 받은 위치는 평균 8.9m(박스 밖 2)다. 1-2 왕복은 2회(린델뢰프·카마라)','WS → `data/2026-10-14-avl-fenerbahce-suzuki-passes.json`','undecided','측정 완료(판정 대상 아님) — 아래 H5 판정',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(52,55,13,'H5','D0','스위핑 유무(스위퍼 vs 볼 플레잉)','`KeeperSweeper` 0건이고 박스 밖 비패스 행동도 0건이다. 17′ 1대1 돌진 선방(Sky 「rushed out」(뛰쳐나왔다) 뛰쳐나왔다)은 박스 안 행동이다. 롱 배급 7개(성공 4) 중 전반 3개는 모두 우측, 후반 4개는 좌측 3·우측 1이다','WS · Sky','match','스위핑 없음 → 스위퍼 근거 부재 — 단일 경기다. 브렌트포드전에서는 `KeeperSweeper` 2건이 있었다(정본 교정 근거)',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(53,55,14,'H5','D0','스즈키 = 볼 플레잉 키퍼 · FotMob 히트맵이 볼 플레잉 모양이다','FotMob 히트맵 34점이 **100% 골문 앞 줄(0~21m)**에 있다. SofaScore·WS 터치도 같다(같은 원천 이벤트). GK 커널 적합은 **골키퍼·Defend .957** > 골키퍼·Balanced .922 > 스위퍼·Balanced .731 > **볼 플레잉·Build-Up .677** > 스위퍼·Build-Up .576 순이다. 볼 플레잉 커널은 그 위 줄(21~42m)에 50%를 두는데 스즈키는 **0%**다. UEFA 트래킹 평균 위치는 골라인에서 13.8m','FM · K · UEFA','mismatch','히트맵 기하 불일치 — 히트맵 모양은 골키퍼·Defend다. 「볼 플레잉 > 스위퍼」는 행동(스위핑 0)으로만 지지된다. ⚠️ 점유 45% · 3-0 리드 경기라 빌드업이 18체인뿐이다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(54,55,15,'H5·H11','D0','후방 빌드업은 2-4-4 또는 3-2(GK가 CB 사이)이고, 경기 안에서 계속 바뀐다','빌드업 18체인을 분류하면 3-2 6 · 2-4-4 5 · 미분류 7이다. 15분 창마다 섞여 나왔다(표 아래). 3-2일 때 CB 간격은 평균 31.0m, 2-4-4일 때 25.3m다. 전환 원인은 창별 페네르 PPDA(6.1~18.3)와 상관이 보이지 않는다','WS','match','일치(경기 안 전환) · 전환 원인은 판정 불가(표본 18)',NULL,1017,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(55,55,16,'H6','D0','파우 토레스 = 볼 플레잉 CB·Build-Up','점유 그리드는 **볼 플레잉 CB·Aggressive .925 > Build-Up .845(Δ.080)**, 전체 그리드는 .942 vs .908(Δ.034 무결정)이다. 패스 출발 평균 34.0m, 42m 이상 출발 13/49, 평균 패스 23.1m · 롱 8% · 전진 패스 20(성공 17 · 두 CB 중 최다)이다. 수비 성공 13건은 평균 22.9m이고 클리어가 8건이다','WS · K','partial','전진 패스 허브(Build-Up 서술)는 맞다. 「DM처럼 올라선다」는 기하는 린델뢰프보다 6.5m 낮다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(56,55,17,'H6','D0','린델뢰프 = 볼 플레잉 CB·Aggressive','점유 그리드 **Aggressive .841 1위**(Build-Up .739, Δ.10). 패스 출발 평균 **40.5m**(전반 47.1m · 21/43이 42m 이상), 평균 패스 18.3m · 롱 2%. 수비 성공은 전반 평균 **40.8m**(4건 중 3건이 42m 이상 — 전진 차단), 후반 14.6m','WS · K','match','Aggressive 일치. ⚠️ 「점유 시 올라섬」은 오히려 린델뢰프가 크다 — Build-Up 성향이 섞여 있다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(57,55,18,'H7','D0','카마라는 낮게 CB와 주고받고 바클리가 더 자유롭다','카마라↔CB 패스 **20회**(카마라→CB 12 · CB→카마라 8) vs 바클리 13회. 평균 x 카마라 51.7 < 바클리 55.8. 좌우 범위 카마라 45.5m < 바클리 54.3m. 카마라는 우 하프스페이스 21/45, 바클리는 좌 하프스페이스 23/50 + 좌측 터치라인 6','WS · Tanswell','match','Tanswell 19:36Z 「Emery has given license for Barkley (sometimes Kamara…) to jump and press」(에메리는 바클리에게는, 때로는 카마라에게도, 뛰어나가 압박할 권한을 줬다)(에메리가 바클리에게(때로는 카마라에게도) 튀어나가 압박할 재량을 줬다)',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(58,55,19,'H7','D0','공격 측면에 따라 카마라가 더 높이 올라간다','카마라 평균 x는 좌측 전개 체인 **59.2m**(y 46 — 중앙으로 이동), 우측 전개 48.3m다. 바클리는 좌 55.0 · 우 57.6이다','WS','match','단 카마라가 오르는 쪽은 좌측 전개다. H4의 「우측 빌드업」과 방향이 반대다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(59,55,20,'H8','D0','만잠비는 드리블러이고 패스·슛 정교함은 낮다','테이크온 1/4(UEFA 드리블 5시도 1성공). 볼 운반 15회(시즌 p90 17.9), 전진 운반 1(시즌 p90 3.0), 볼 뺏김 3 · 소유 상실 13. 패스 24/29(**83%** · 시즌 90.0%), 키패스 2, 전진 패스 성공 6. 슛 2(유효 1 · 골 1 · 코너 상황) xG .24 · **xGOT .76**. PK 획득(20 Minuten 「herrlichen Finte」(화려한 페인트) 멋진 페인트)','SS · WS · UEFA','partial','드리블 빈도(시도·운반)와 패스 정확도 하락은 맞다. 드리블 성공률은 낮았고, 마무리는 이 경기 오히려 정교했다(xGOT > xG)',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
