INSERT INTO match_hypotheses VALUES(76,55,37,'H13','D0','알리송은 전진 능력이 좋고 로저스 느낌이다','17분 동안 테이크온 **3/3**, 전진 운반 2(49m · 75′ 자기 진영 탈환 후 약 33m 단독 운반 → 키패스), 키패스 2, xA .60, **도움 1**. UEFA 스프린트 9/17분. 로저스 25/26 PL p90은 드리블 성공 1.15 · 키패스 1.29(SofaScore 시즌 통계)','WS · SS · UEFA','match','일치(약) — 17분 표본이라 등급 LOW',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(77,55,38,'H14','D0','맥긴(CAM)↔알리송(RM) 분업(맥긴 중앙 → 알리송 윙어)','교체 후 맥긴→알리송 1(81′ 우측 터치라인 수신), 알리송→맥긴 0. 알리송 수신 1회','WS','undecided','표본',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(78,55,39,'H15','D0','음바예는 하프스페이스로 운반, 알리송은 골라인 근처까지 가서 크로스','음바예 운반 14회의 끝 위치: 하프스페이스 6 · 측면(골라인 전) 5 · 골라인 근처 1. 운반 뒤 행동: 패스 8 · 슛 3 · 컷백 2. **음바예 도움(72′)은 x95 · 좌 하프스페이스 골라인 근처에서 컷백**했다. **알리송 도움(89′)은 x91에서 돌파 → x97 · 우 하프스페이스 골라인 근처에서 낮은 패스**를 넣었다. 둘 다 크로스 한정자(Cross)는 없다','WS','partial','음바예 하프스페이스는 맞다. 두 도움은 같은 모양(골라인 근처 하프스페이스 컷백)이라 「알리송만 더 깊다」는 이 경기로 가르지 못한다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(79,55,40,NULL,'D0','음바예 햄스트링 이상으로 교체','79′ SofaScore `incidentClass=injury` · 77′ 경기 일시 중단(Virgilio 「Gara momentaneamente sospesa … per infortunio」(부상으로 경기가 일시적으로 중단됐다) 부상으로 경기 일시 중단). 부위·정도는 아래 「부상 추적」','SS · Virgilio','match','일치(부상 교체) · 부위·정도 D+2 재판정',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
