INSERT INTO match_hypotheses VALUES(146,62,28,'C1','D1','고메스가 명단상 RB였나','D-1 회견(BeanymanSports IfHtDTgrpNg [00:31]~[01:33]) 에메리: 완비사카 「three or four weeks」(3~4주) · 루헤리 「more or less 2 months」(약 2개월) · 마첸 「training with us this week」(이번 주 팀 훈련 합류) · 「we have enough players. It''s not excuses … we''ll find solution … in each position」(선수는 충분하다 · 변명이 아니다 · 각 포지션에서 해법을 찾겠다) · 팬 채널 3곳이 「Gomes at right back → stepped into midfield · Mings dropping to make a back three · McGinn out to the right」(고메스는 라이트백에서 미드필드로 올라섰다 · 밍스는 내려와 백3을 만들었다 · 맥긴은 오른쪽으로 나갔다)(auto-caption)로 같은 구조 서술','IfHtDTgrpNg · TBFCxm45v5A [01:11][10:29] · um4HoJeNzYg [07:38][08:08] · bekVcNRpJ1Q [01:39][02:11]','match','새 사실 유지 + 사유 확정: 전문 풀백 부재는 부상 강제(가용성 우선 · docs/70) · 고메스 RB 「왜」에 대한 에메리 직접 발언은 경기 후에도 0건',140,1117,'바이킹전 D+1 보강 회차(2026-10-22 11:00~ KST) — reports/match-watch/2026-10-21-avl-viking-d1-sources.md · 전사 6편(뮤트 pot 경로) · load_match_extras.py','D+1 정정 — 요약 경유 기사 + auto-caption 전사 · 원 판정 행은 보존(supersedes)','2026-10-22T11:27:55');
INSERT INTO match_hypotheses VALUES(147,62,10,'M2','D1','고메스 볼 캐리가 좋다','운반(추정 · core.whoscored.carry_est · player_matches.stats_json carry_est_*) — 10+ 전진 운반: 알리송 5 · 고메스 4 · 린델뢰프 4 · 맥긴 3 · 가르나초 3(18분) · 토레스 2 · 음바예 2 · 바클리 0. 전진 거리 합: 알리송 165.2m · 토레스 131.6m · 고메스 123.7m · 린델뢰프 115.2m · 맥긴 86.8m · 바클리 20.0m. 전체 추정 쌍: 린델뢰프·맥긴 61 · 토레스 59 · 고메스 55','D+0 손계산(10+ 전진 4회 팀 최다 · CB 각 3)을 같은 정의의 스크립트로 재현 — 고메스 4는 유지되나 **팀 최다가 아니라 알리송 5 다음 공동 2위(린델뢰프 4)**이고 CB는 린델뢰프 4·토레스 2로 갈린다. 「볼 캐리가 좋다」는 미드필더 짝 바클리(0 · 20m)·맥긴(3 · 87m)과 견주면 성립하지만, 전진 운반의 무대는 측면(알리송)과 후방(CB)이 더 컸다','partial','부분 일치 유지 — 정량 근거를 추정 지표로 정형화(CARRY_EST_METHOD). 추정이라 ±1~2회 오차 가능 · SofaScore 운반 지표는 경기 단위 미제공',122,1093,'WhoScored 2029164 matchCentreData(scope=full · reports/match-watch/data/2026-10-21-avl-ws-2029164.json · 2026-10-22 저장) → core.whoscored.carry_est(scripts/load_carry_est.py)','MEDIUM — 운반은 **추정**(Opta에 캐리 이벤트 없음 · 수신 좌표→다음 볼 이벤트 Δx · 15초 창 · 세트피스 제외) · 손계산(D+0)과 같은 정의를 core에 올려 재현','2026-10-22T16:13:10');
INSERT INTO match_hypotheses VALUES(148,62,13,'M2','D2','부엔디아 내려오며 받아 주는 모습이 많다','정형 재계산(recv_*): 부엔디아 수신 35 · 수신 평균 x 63.6 · 마지막 3분의 1(x≥66.7) 수신 18(51%) · x≥80 7 · 전진 수신(+10) 10 — 고메스 수신 58 · x̄ 58.0 / 맥긴 61 · x̄ 57.5보다 여전히 높다. D0 손계산(36 · 62.5)과 일치.','player_matches.stats_json recv_n/recv_x_mean/recv_deep_n/recv_deep80_n/recv_prog_n(match 126) · 방법 recv_method','partial','판정 불변(부분 일치) — 「내려와 받는다」는 후반 구간에만 뚜렷하다는 D0 판정을 정형 값이 그대로 지지. 수신의 절반이 마지막 3분의 1이라 「많이 내려왔다」로는 못 읽는다.',125,NULL,'core.whoscored.receptions(WS matchCentreData 2029164 · reports/match-watch/data/2026-10-21-avl-ws-2029164.json · scripts/load_ws_player_extras.py --apply 2026-10-22) · 부모 세션 WP-M1','HIGH — D0의 콘솔 손계산을 core 함수(recv_method 명시)로 재현 · 값 차이는 귀속 창(10초·같은 팀 다음 볼 이벤트) 정의 차이 1~2건 수준','2026-10-22T16:59:04');
INSERT INTO match_hypotheses VALUES(149,62,19,'M4','D2','부엔디아·맥긴 내려와서 빌드업 관여','정형 재계산(recv_*): 맥긴 수신 61(팀 1위) · x̄ 57.5 · 전진 수신 14(팀 2위 · 알리송 28) · 고메스 수신 58(2위) · x̄ 58.0 · 전진 수신 7 / 부엔디아 수신 35 · 전진 10. D0(맥긴 63 · 57.0)과 일치.','player_matches.stats_json recv_*(match 126) · 연결 관여 27.7%(D0) · 방법 recv_method','partial','판정 불변(부분 일치) — 맥긴·고메스가 수신 1·2위로 「빌드업 관여」는 일치, 부엔디아는 수신 수·위치 모두 마무리 쪽이라 부분.',131,NULL,'core.whoscored.receptions(WS matchCentreData 2029164 · reports/match-watch/data/2026-10-21-avl-ws-2029164.json · scripts/load_ws_player_extras.py --apply 2026-10-22) · 부모 세션 WP-M1','HIGH — D0의 콘솔 손계산을 core 함수(recv_method 명시)로 재현 · 값 차이는 귀속 창(10초·같은 팀 다음 볼 이벤트) 정의 차이 1~2건 수준','2026-10-22T16:59:04');
INSERT INTO match_hypotheses VALUES(150,62,1,'M1','D2','수비 4-4-2 — 밍스·토레스·린델뢰프·고메스(RB) / 음바예·바클리·맥긴·알리송 / 부엔디아·잭슨','실측 RB 존 수비 액션 고메스 6 · 맥긴 5(불변). D+2 영상 7편이 교대를 같은 방향으로 서술 — Justin Talks Villa 「they sort of took it in turns covering right back」(둘이 번갈아 라이트백을 커버했다) · C&B 「flip and rotation between the pair of them」(둘이 뒤바뀌며 순환했다) · Penno 「even McGinn was doing it second half」(후반엔 맥긴도 그렇게 했다). 비보유 형태는 Bardell(Yahoo) 「without the ball it was essentially the same 4-2-3-1 shape」(공이 없을 때는 사실상 평소와 같은 4-2-3-1) · AVNF 「4-4-2」','WS · 영상(auto-caption) · Yahoo/Roundtable','partial','유지·보강 — 백4 골격 맞음 · RB는 고메스 단독이 아니라 맥긴과 교대',113,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(151,62,11,'M2','D2','고메스 좌우로 가로지르며 거의 프리롤','실측 좌측 레인 5/75(7%) 불변. 서사가 갈린다 — 사용자 쪽: Terrace View 「one minute he was center mid, one minute he was out on the left」(한때는 중앙, 한때는 왼쪽) · Kelland(substack) 「often in central areas but sometimes out wide」(주로 중앙, 때로 측면) · Villans·C&B 「everywhere」(어디에나). 실측 쪽: UTV 「we really locked in on that right-hand side」(오른쪽에 확실히 집중했다) · AVNF 「more onto the right side」(오른쪽에 치우쳤다)','WS · 영상 6편 · substack','mismatch','유지 — 실측 채택(불변규칙 3) · 팬 인상 서술과 충돌을 obs#1128에 기록',123,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(152,62,12,'M2','D2','바클리 2선 높이까지 올라가 빌드업을 푼다','구간 실측 불변(0–23′ 바클리 x 66.0 > 고메스 58.6). 에메리 회견 「always playing eight number or 10 number」(8번이든 10번이든 뛴다). Terrace View는 「15 minutes in… Gomez is doing more in the middle… than Barkley」(15분까지는 고메스가 바클리보다 중원에서 더 많이 했다)로 실측과 반대 서술','WS · 회견 전사 · 영상','partial','유지 — 0-0 구간에만 일치 · 반대 서술은 팬 인상(실측 채택)',124,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(153,62,15,'M3','D2','잭슨이 왼쪽으로 벌리면 음바예가 중앙으로 들어와 톱','영상 13편·블로그 4편·노르웨이어 기사 4곳 모두 잭슨↔음바예 자리 교환 서술 0건. UTV 「He did have to drop in there at times」(음바예가 때로 안으로 내려와야 했다 — 톱 이동이 아니라 하강) · Rogers 「hovering on the by lines」(바이라인에 머물렀다) · Kelland 「tight to the touchline」(터치라인에 붙어)','WS · 영상 · substack','mismatch','유지 — 단발 장면 가능성은 남지만 서술·실측 모두 0',127,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(154,62,17,'M4','D2','3-4-2-1로도 볼 수 있다(vs 3-2-5)','형태를 숫자로 말한 곳: AVNF 「a three, a two, and then a kind of five in attack」(공격 때 3, 2, 그리고 5 비슷한 형태) 1편 · C&B 「352 or 343」 · 3-4-2-1 명시 0. Bardell 「Gomes moved into midfield, McGinn pushed forward to operate alongside Emi Buendia」(고메스는 중원으로, 맥긴은 전진해 부엔디아와 나란히) — 3-2-5에 2명의 10번을 둔 서술','영상 · Yahoo/Roundtable','partial','유지 — 위치 높이는 3-2-5 · 게임 슬롯 적합은 3-4-2-1(프리셋 B)',129,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(155,62,20,'M4','D2','음바예 = 인사이드 포워드(안쪽·뒷공간 침투)','회견 기자 질문 전제 「It seemed that you asked them to play wider today」(오늘 더 넓게 서라고 한 것 같다 — 음바예·알리송)에 에메리가 부정하지 않음 · Bardell 「Ibrahim Mbaye and Alysson holding the width」(음바예·알리송이 폭 유지) · Kelland 「tight to the touchline」(터치라인에 바짝 붙어). 반대 서술 Justin Talks Villa(영상) 1건','회견 전사 · Yahoo · substack · 영상','mismatch','유지 — 이 경기는 터치라인 윙어 · 쟁점 #7 윙어 쪽 표본',132,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(156,62,21,'M4','D2','바클리 = cm_playmaker/Roaming(사용자 확정)','에메리 「always playing eight number or 10 number improving in our demands defensively. I am pushing him a lot defensively」(8번이든 10번이든 수비 요구를 채우며 나아지고 있다 · 수비를 많이 다그친다) · Justin Talks Villa 「deep-lying midfielder」(딥라잉 미드필더) · C&B 「Ross Barkley come in and kind of filled that gap」(틸레만스의 볼 플레잉 공백을 바클리가 메웠다)','회견 전사 · 영상','partial','유지 — 사용자 확정 cm_playmaker/Roaming 그대로 · 커널 DM 칸 dm_dlp/Roaming과 서사(딥라잉)가 같은 방향',133,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(157,62,25,'R1','D2','⭐ 알리송 중점 — 평가·발언·분석 영상','브라질 매체 확보(D+1 0건 해소): Zona Mista(10-22) 「Um dos grandes destaques da vitória do Aston Villa」(빌라 승리의 가장 돋보인 선수 중 한 명) · Itatiaia(10-22) 「O atacante brasileiro foi eleito pelo clube inglês o melhor em campo.」(브라질 공격수가 잉글랜드 구단이 뽑은 경기 최우수 선수가 됐다) · Canal 38(고향 아푸카라나). 본인(AVFC 공식 영상) 「For me, it was a dream night for me, for my family.」(나와 가족에게 꿈같은 밤이었다). ge.globo·UOL·Lance! 여전히 0','포르투갈어 기사 3 · AVFC 영상(auto-caption)','match','유지 — 평가 축 채움 · 대형 매체 0은 사유 기록',144,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
INSERT INTO match_hypotheses VALUES(158,62,26,'R2','D2','⭐ 가설: 맥긴·고메스가 중원에서 경기를 푸는 축','실측 불변(맥긴 14.7% · 고메스 13.2% · 상위 연결 쌍 우측 삼각형). UTV 「pretty much played on the same position」(맥긴과 고메스가 거의 같은 자리에서 뛰었다) · Bardell 「he and Buendia were finding some lovely pockets of space between the lines」(맥긴과 부엔디아가 라인 사이 공간을 잘 찾았다) · LiveScore(FotMob 경유) 고메스 라인 브레이킹 패스 7','WS · 영상 · Yahoo','match','유지 — 무대는 오른쪽',138,1128,'mw-avl-viking-d2(2026-10-23) · 리포트 「D+2 추적」 절 · 영상 13편(match_videos #365~#377) · 블로그 4편 · 노르웨이어 4곳','판정은 실측(WS 2029164·SS·FM) 기준 유지 — 서사는 팬 채널 auto-caption 위주(D등급) · 회견은 1차 전사','2026-10-23T20:23:15');
